function scalar(value: number): string {
  const literal = String(value)
  return /[.e]/i.test(literal) ? literal : `${literal}.0`
}

function matrix(layer: CnnWeights, index: number): string {
  const values = Array.from(layer.weights.subarray(index * 16, index * 16 + 16), scalar)
  if (values.length !== 16) throw new Error(`Invalid CNN matrix: ${layer.name}`)
  return `mat4x4f(${values.join(', ')})`
}

function bindings(count: number): string {
  return Array.from({ length: count }, (_, index) => `
@group(0) @binding(${index + 1}) var source${index}: texture_2d<f32>;
fn load${index}(p: vec2i) -> vec4f {
  return textureLoad(source${index}, clamp(p, vec2i(0), vec2i(textureDimensions(source${index})) - vec2i(1)), 0);
}`).join('\n')
}

function convolution(layer: CnnWeights, inputs: readonly number[], first: boolean, concat: boolean): CnnPass {
  const steps: string[] = []
  if (concat) {
    for (let input = 0; input < inputs.length; input++) {
      steps.push(`let pixel${input} = load${input}(coord);`)
      steps.push(`result += ${matrix(layer, input * 2)} * max(pixel${input}, vec4f(0.0));`)
      steps.push(`result += ${matrix(layer, input * 2 + 1)} * max(-pixel${input}, vec4f(0.0));`)
    }
  } else {
    for (let x = -1; x <= 1; x++) {
      for (let y = -1; y <= 1; y++) {
        const index = (x + 1) * 3 + y + 1
        const pixel = `pixel${index}`
        steps.push(`let ${pixel} = load0(coord + vec2i(${x}, ${y}));`)
        steps.push(`result += ${matrix(layer, index)} * ${first ? pixel : `max(${pixel}, vec4f(0.0))`};`)
        if (!first) steps.push(`result += ${matrix(layer, index + 9)} * max(-${pixel}, vec4f(0.0));`)
      }
    }
  }
  return {
    name: layer.name,
    scale: 1,
    inputs,
    wgsl: `${bindings(inputs.length)}
@fragment fn fragmentMain(@builtin(position) position: vec4f) -> @location(0) vec4f {
  let coord = vec2i(position.xy);
  var result = vec4f(${Array.from(layer.bias, scalar).join(', ')});
  ${steps.join('\n  ')}
  return result;
}`,
  }
}

function shuffle(inputs: readonly number[]): CnnPass {
  const channels = inputs.length === 2
    ? 'vec3f(load1(coord)[channel])'
    : 'vec3f(load1(coord)[channel], load2(coord)[channel], load3(coord)[channel])'
  return {
    name: 'pixel_shuffle',
    scale: 2,
    inputs,
    wgsl: `${bindings(inputs.length)}
@fragment fn fragmentMain(@builtin(position) position: vec4f) -> @location(0) vec4f {
  let outputPixel = vec2i(position.xy);
  let coord = outputPixel / 2;
  let channel = u32(outputPixel.x % 2 + (outputPixel.y % 2) * 2);
  let sourcePosition = position.xy * 0.5 - vec2f(0.5);
  let base = vec2i(floor(sourcePosition));
  let fraction = fract(sourcePosition);
  let row0 = mix(load0(base), load0(base + vec2i(1, 0)), fraction.x);
  let row1 = mix(load0(base + vec2i(0, 1)), load0(base + vec2i(1, 1)), fraction.x);
  let original = mix(row0, row1, fraction.y).rgb;
  return vec4f(clamp(original + ${channels}, vec3f(0.0), vec3f(1.0)), 1.0);
}`,
  }
}

/** No uniform or sampler bindings: the renderer adds only the fullscreen vertex shader. */
export const CNN_PASSES: readonly CnnPass[] = [
  ...CNN_S_WEIGHTS.map((layer, index) => convolution(layer, [index - 1], index === 0, false)),
  shuffle([-1, 3]),
]

/** Kept available for host budget comparisons; the shipping default is S. */
export const CNN_M_PASSES: readonly CnnPass[] = [
  ...CNN_M_WEIGHTS.map((layer, index) => convolution(layer,
    index < 7 ? [index - 1] : [0, 1, 2, 3, 4, 5, 6], index === 0, index >= 7)),
  shuffle([-1, 7, 8, 9]),
]
